window.__SHB_EGYPTIAN_BOOK_QUESTIONS__=(window.__SHB_EGYPTIAN_BOOK_QUESTIONS__||[]).concat([{"id":"EB-paediatrics-pulmonology-accepted-CH08-Q001","spec":"eb-respiratory","topic":0,"tag":"Egyptian book","kind":"Physiology","q":"Theorganforagasexchangeinfetus","o":["Amnioticfluid","Umbilicalcord","Placenta","Lungs"],"ol":["A","B","C","D"],"k":2,"ex":"Before birth, the placenta is the principal site of gas exchange. Oxygen diffuses from maternal blood to fetal blood and carbon dioxide moves in the opposite direction. Fetal lungs are fluid-filled and do not perform the gas-exchange role until after birth.","more":"Before birth, the placenta is the principal site of gas exchange. Oxygen diffuses from maternal blood to fetal blood and carbon dioxide moves in the opposite direction. Fetal lungs are fluid-filled and do not perform the gas-exchange role until after birth.\n\nCurriculum alignment: Neonatology 2024–25, fetal circulation and transition at birth; Respiratory 2024, p.3: fetal/neonatal respiratory anatomy.\n\nHigh-yield point: Before birth, the placenta is the principal site of gas exchange.","ao":true,"eb":true,"aoClass":"Accepted","aoReview":false,"aoTitle":"CH08-Q001 — Q1: Gas-exchange organ in the fetus","aoSource":"Question-bank MD page 107 · Printed page 195 · Answer-key PDF page 116 · Original question Q1","aoSystem":"الجهاز التنفسي","aoPart":"","kx":false,"ebSourceFile":"Paediatrics_Pulmonology_Accepted.md","_genhy":true},{"id":"EB-paediatrics-pulmonology-accepted-CH08-Q002","spec":"eb-respiratory","topic":0,"tag":"Egyptian book","kind":"Pathophysiology","q":"Thefunctionofthepulmonarysurfactant","o":["Maintainsthesurfacetension","Increasesthesurfacetension","Decreasesthesurfacetension","Noneoftheabove"],"ol":["A","B","C","D"],"k":2,"ex":"Pulmonary surfactant lowers surface tension at the air–liquid interface in alveoli. This increases lung compliance, reduces the work of breathing and helps prevent end-expiratory alveolar collapse (atelectasis), especially in premature infants.","more":"Pulmonary surfactant lowers surface tension at the air–liquid interface in alveoli. This increases lung compliance, reduces the work of breathing and helps prevent end-expiratory alveolar collapse (atelectasis), especially in premature infants.\n\nCurriculum alignment: Neonatology 2024–25, respiratory distress syndrome; Respiratory 2024, physiology and neonatal respiratory distress.\n\nHigh-yield point: Pulmonary surfactant lowers surface tension at the air–liquid interface in alveoli.","ao":true,"eb":true,"aoClass":"Accepted","aoReview":false,"aoTitle":"CH08-Q002 — Q2: Function of pulmonary surfactant","aoSource":"Question-bank MD page 107 · Printed page 195 · Answer-key PDF page 116 · Original question Q2","aoSystem":"الجهاز التنفسي","aoPart":"","kx":false,"ebSourceFile":"Paediatrics_Pulmonology_Accepted.md","_genhy":true},{"id":"EB-paediatrics-pulmonology-accepted-CH08-Q008","spec":"eb-respiratory","topic":0,"tag":"Egyptian book","kind":"Pathophysiology","q":"Common cold is associated with excessive lacrimationbecauseof","o":["Conjunctivitis","Allergy","Blockedlacrimalductinnose","Blockedlacrimalductineye"],"ol":["A","B","C","D"],"k":2,"ex":"Nasal mucosal inflammation and congestion can obstruct the distal nasolacrimal drainage pathway where it opens into the nose. Tear drainage is impaired and watering of the eyes occurs (epiphora).","more":"Nasal mucosal inflammation and congestion can obstruct the distal nasolacrimal drainage pathway where it opens into the nose. Tear drainage is impaired and watering of the eyes occurs (epiphora).\n\nCurriculum alignment: Respiratory 2024, pp.3–5: upper airway anatomy and common respiratory infections; concept linked to nasolacrimal drainage anatomy.\n\nHigh-yield point: Nasal mucosal inflammation and congestion can obstruct the distal nasolacrimal drainage pathway where it opens into the nose.","ao":true,"eb":true,"aoClass":"Accepted","aoReview":false,"aoTitle":"CH08-Q008 — Q8: Excessive lacrimation during the common cold","aoSource":"Question-bank MD page 107 · Printed page 195 · Answer-key PDF page 116 · Original question Q8","aoSystem":"الجهاز التنفسي","aoPart":"","kx":false,"ebSourceFile":"Paediatrics_Pulmonology_Accepted.md","_genhy":true},{"id":"EB-paediatrics-pulmonology-accepted-CH08-Q011","spec":"eb-respiratory","topic":0,"tag":"Egyptian book","kind":"Diagnosis","q":"Noisybreathingbecauseofinspiratoryobstruction","o":["Wheez","Stridor","Crepitation","None"],"ol":["A","B","C","D"],"k":1,"ex":"Stridor is a harsh, often high-pitched sound produced by turbulent airflow through a narrowed upper airway and is typically more prominent during inspiration in extrathoracic obstruction. Wheeze generally arises from lower-airway narrowing and is more prominent during expiration.","more":"Stridor is a harsh, often high-pitched sound produced by turbulent airflow through a narrowed upper airway and is typically more prominent during inspiration in extrathoracic obstruction. Wheeze generally arises from lower-airway narrowing and is more prominent during expiration.\n\nCurriculum alignment: Respiratory 2024, pp.3–4 and pp.11–12: upper vs lower airway obstruction, stridor and laryngomalacia.\n\nHigh-yield point: Stridor is a harsh, often high-pitched sound produced by turbulent airflow through a narrowed upper airway and is typically more prominent during inspiration in extrathoracic obstruction.","ao":true,"eb":true,"aoClass":"Accepted","aoReview":false,"aoTitle":"CH08-Q011 — Q11: Noisy breathing due to inspiratory upper-airway obstruction","aoSource":"Question-bank MD page 107 · Printed page 195 · Answer-key PDF page 116 · Original question Q11","aoSystem":"الجهاز التنفسي","aoPart":"","kx":false,"ebSourceFile":"Paediatrics_Pulmonology_Accepted.md","_genhy":true},{"id":"EB-paediatrics-pulmonology-accepted-CH08-Q013","spec":"eb-respiratory","topic":0,"tag":"Egyptian book","kind":"Differential Diagnosis","q":"Thecausesofthestridor,except","o":["Croup","Foreignbody","Bronchialasthma","Vascularring"],"ol":["A","B","C","D"],"k":2,"ex":"Stridor usually indicates upper-airway obstruction. Croup, an inhaled upper-airway foreign body and vascular rings can produce stridor. Bronchial asthma is a lower-airway obstructive disorder and typically causes expiratory wheeze, so it is the exception.","more":"Stridor usually indicates upper-airway obstruction. Croup, an inhaled upper-airway foreign body and vascular rings can produce stridor. Bronchial asthma is a lower-airway obstructive disorder and typically causes expiratory wheeze, so it is the exception.\n\nCurriculum alignment: Respiratory 2024, pp.11–17: acute/chronic stridor, croup, epiglottitis; pp.29 and 3: foreign body and airway physiology.\n\nHigh-yield point: Stridor usually indicates upper-airway obstruction.","ao":true,"eb":true,"aoClass":"Accepted","aoReview":false,"aoTitle":"CH08-Q013 — Q13: Cause of stridor: exception","aoSource":"Question-bank MD page 108 · Printed page 196 · Answer-key PDF page 116 · Original question Q13","aoSystem":"الجهاز التنفسي","aoPart":"","kx":false,"ebSourceFile":"Paediatrics_Pulmonology_Accepted.md","_genhy":true},{"id":"EB-paediatrics-pulmonology-accepted-CH08-Q015","spec":"eb-respiratory","topic":0,"tag":"Egyptian book","kind":"Diagnosis","q":"Commonestorganismforacuteepiglottitis","o":["H.influenzaB","Pneumococcus","Staphylococcus","Streptococcus"],"ol":["A","B","C","D"],"k":0,"ex":"Haemophilus influenzae type b (Hib) was the classic and historically most common cause of childhood acute epiglottitis. Hib vaccination has greatly reduced its incidence, and other bacteria can now be responsible. The question reflects classic teaching and remains clinically relevant, but the epidemiology is vaccine-era dependent.","more":"Haemophilus influenzae type b (Hib) was the classic and historically most common cause of childhood acute epiglottitis. Hib vaccination has greatly reduced its incidence, and other bacteria can now be responsible. The question reflects classic teaching and remains clinically relevant, but the epidemiology is vaccine-era dependent.\n\nCurriculum alignment: Respiratory 2024, pp.16–17: epiglottitis and its bacterial cause; course emphasizes Hib. Extended Beyond Core Curriculum because post-vaccine epidemiology has changed.\n\nHigh-yield point: Haemophilus influenzae type b (Hib) was the classic and historically most common cause of childhood acute epiglottitis.","ao":true,"eb":true,"aoClass":"Accepted","aoReview":false,"aoTitle":"CH08-Q015 — Q15: Common organism causing acute epiglottitis","aoSource":"Question-bank MD page 108 · Printed page 196 · Answer-key PDF page 116 · Original question Q15","aoSystem":"الجهاز التنفسي","aoPart":"","kx":false,"ebSourceFile":"Paediatrics_Pulmonology_Accepted.md","_genhy":true},{"id":"EB-paediatrics-pulmonology-accepted-CH08-Q016","spec":"eb-respiratory","topic":0,"tag":"Egyptian book","kind":"Diagnosis","q":"The respiratory cause of the subconjunctiva haemorrhage","o":["Bronchitis","Whoopingcough","Croup","Bronchiectasis"],"ol":["A","B","C","D"],"k":1,"ex":"Paroxysms of forceful coughing in pertussis can raise intrathoracic and venous pressure, causing small conjunctival vessels to rupture and produce subconjunctival haemorrhage.","more":"Paroxysms of forceful coughing in pertussis can raise intrathoracic and venous pressure, causing small conjunctival vessels to rupture and produce subconjunctival haemorrhage.\n\nCurriculum alignment: Respiratory 2024, respiratory infection and cough; Infectious 2024, pertussis section.\n\nHigh-yield point: Paroxysms of forceful coughing in pertussis can raise intrathoracic and venous pressure, causing small conjunctival vessels to rupture and produce subconjunctival haemorrhage.","ao":true,"eb":true,"aoClass":"Accepted","aoReview":false,"aoTitle":"CH08-Q016 — Q16: Respiratory cause of subconjunctival haemorrhage","aoSource":"Question-bank MD page 108 · Printed page 196 · Answer-key PDF page 116 · Original question Q16","aoSystem":"الجهاز التنفسي","aoPart":"","kx":false,"ebSourceFile":"Paediatrics_Pulmonology_Accepted.md","_genhy":true},{"id":"EB-paediatrics-pulmonology-accepted-CH08-Q023","spec":"eb-respiratory","topic":0,"tag":"Egyptian book","kind":"Diagnosis","q":"Pleuritiscanreferthepainto","o":["Shoulder","Abdomen","Both","None"],"ol":["A","B","C","D"],"k":2,"ex":"Inflammation of the parietal pleura causes sharp pain with breathing. Diaphragmatic pleural irritation can refer pain to the shoulder via the phrenic nerve (C3–C5), while lower diaphragmatic irritation may be perceived in the upper abdomen. Both sites are possible depending on the region involved.","more":"Inflammation of the parietal pleura causes sharp pain with breathing. Diaphragmatic pleural irritation can refer pain to the shoulder via the phrenic nerve (C3–C5), while lower diaphragmatic irritation may be perceived in the upper abdomen. Both sites are possible depending on the region involved.\n\nCurriculum alignment: Respiratory 2024, pp.24–26: pleural disease, pleuritic pain and pleural effusion.\n\nHigh-yield point: Inflammation of the parietal pleura causes sharp pain with breathing.","ao":true,"eb":true,"aoClass":"Accepted","aoReview":false,"aoTitle":"CH08-Q023 — Q23: Referred pain from pleuritis","aoSource":"Question-bank MD page 108 · Printed page 196 · Answer-key PDF page 116 · Original question Q23","aoSystem":"الجهاز التنفسي","aoPart":"","kx":false,"ebSourceFile":"Paediatrics_Pulmonology_Accepted.md","_genhy":true},{"id":"EB-paediatrics-pulmonology-accepted-CH08-Q025","spec":"eb-respiratory","topic":0,"tag":"Egyptian book","kind":"Investigation","q":"The radiological sign of the staphylococcal pneumonia","o":["Honeycombappearance","Atelectasis","Consolidation","Pneumatocele"],"ol":["A","B","C","D"],"k":3,"ex":"Staphylococcal pneumonia can produce necrotizing/cavitating disease and thin-walled air-filled pneumatoceles. These may rupture and cause pneumothorax.","more":"Staphylococcal pneumonia can produce necrotizing/cavitating disease and thin-walled air-filled pneumatoceles. These may rupture and cause pneumothorax.\n\nCurriculum alignment: Respiratory 2024, pp.22–24: pneumonia pathogens, complications and radiographic features.\n\nHigh-yield point: Staphylococcal pneumonia can produce necrotizing/cavitating disease and thin-walled air-filled pneumatoceles.","ao":true,"eb":true,"aoClass":"Accepted","aoReview":false,"aoTitle":"CH08-Q025 — Q25: Radiological sign of staphylococcal pneumonia","aoSource":"Question-bank MD page 109 · Printed page 197 · Answer-key PDF page 116 · Original question Q25","aoSystem":"الجهاز التنفسي","aoPart":"","kx":false,"ebSourceFile":"Paediatrics_Pulmonology_Accepted.md","_genhy":true},{"id":"EB-paediatrics-pulmonology-accepted-CH08-Q026","spec":"eb-respiratory","topic":0,"tag":"Egyptian book","kind":"Complications","q":"Complicationofthestaphylococcalpneumonia","o":["Atelectasis","Pneumothorax","Emphysema","Bronchitis"],"ol":["A","B","C","D"],"k":1,"ex":"Staphylococcal pneumonia may cause necrosis, pneumatoceles, empyema and pneumothorax. Pneumothorax may occur when a pneumatocele ruptures into the pleural space.","more":"Staphylococcal pneumonia may cause necrosis, pneumatoceles, empyema and pneumothorax. Pneumothorax may occur when a pneumatocele ruptures into the pleural space.\n\nCurriculum alignment: Respiratory 2024, pp.22–24: staphylococcal pneumonia and complications.\n\nHigh-yield point: Staphylococcal pneumonia may cause necrosis, pneumatoceles, empyema and pneumothorax.","ao":true,"eb":true,"aoClass":"Accepted","aoReview":false,"aoTitle":"CH08-Q026 — Q26: Complication of staphylococcal pneumonia","aoSource":"Question-bank MD page 109 · Printed page 197 · Answer-key PDF page 116 · Original question Q26","aoSystem":"الجهاز التنفسي","aoPart":"","kx":false,"ebSourceFile":"Paediatrics_Pulmonology_Accepted.md","_genhy":true},{"id":"EB-paediatrics-pulmonology-accepted-CH08-Q028","spec":"eb-respiratory","topic":0,"tag":"Egyptian book","kind":"Diagnosis","q":"The etiological agent of the primary atypical pneumoniais","o":["Mycoplasmapneumoniae","Mycobacteriumtuberculosis","Both","None"],"ol":["A","B","C","D"],"k":0,"ex":"Mycoplasma pneumoniae is a common cause of primary atypical pneumonia in school-age children and adolescents. It often causes a gradual onset of fever, headache and persistent dry cough, with variable radiological findings.","more":"Mycoplasma pneumoniae is a common cause of primary atypical pneumonia in school-age children and adolescents. It often causes a gradual onset of fever, headache and persistent dry cough, with variable radiological findings.\n\nCurriculum alignment: Respiratory 2024, pp.6–8 and pneumonia section.\n\nHigh-yield point: Mycoplasma pneumoniae is a common cause of primary atypical pneumonia in school-age children and adolescents.","ao":true,"eb":true,"aoClass":"Accepted","aoReview":false,"aoTitle":"CH08-Q028 — Q28: Cause of primary atypical pneumonia","aoSource":"Question-bank MD page 109 · Printed page 197 · Answer-key PDF page 116 · Original question Q28","aoSystem":"الجهاز التنفسي","aoPart":"","kx":false,"ebSourceFile":"Paediatrics_Pulmonology_Accepted.md","_genhy":true},{"id":"EB-paediatrics-pulmonology-accepted-CH08-Q029","spec":"eb-respiratory","topic":0,"tag":"Egyptian book","kind":"Diagnosis","q":"Theorganism causingpneumoniaonlyinimmuno- compromisedchild","o":["HIV","Tuberculosis","Pneumocystiscarinni","Staphylococcus"],"ol":["A","B","C","D"],"k":2,"ex":"Pneumocystis jirovecii (formerly P. carinii) causes opportunistic pneumonia, especially in children with severe T-cell immunodeficiency or advanced HIV. The disease may present with progressive dyspnea, hypoxemia and diffuse bilateral interstitial infiltrates.","more":"Pneumocystis jirovecii (formerly P. carinii) causes opportunistic pneumonia, especially in children with severe T-cell immunodeficiency or advanced HIV. The disease may present with progressive dyspnea, hypoxemia and diffuse bilateral interstitial infiltrates.\n\nCurriculum alignment: Respiratory 2024, pneumonia/opportunistic infection content; Immunology 2024, cellular immunodeficiency and opportunistic infections.\n\nHigh-yield point: Pneumocystis jirovecii (formerly P.","ao":true,"eb":true,"aoClass":"Accepted","aoReview":false,"aoTitle":"CH08-Q029 — Q29: Organism associated with pneumonia in immunocompromised children","aoSource":"Question-bank MD page 109 · Printed page 197 · Answer-key PDF page 116 · Original question Q29","aoSystem":"الجهاز التنفسي","aoPart":"","kx":false,"ebSourceFile":"Paediatrics_Pulmonology_Accepted.md","_genhy":true},{"id":"EB-paediatrics-pulmonology-accepted-CH08-Q036","spec":"eb-respiratory","topic":0,"tag":"Egyptian book","kind":"Pathophysiology","q":"Thecausesoftheatelectasisduetointrabronchial obstruction","o":["Foreignbody","Mucusplug","Both","None"],"ol":["A","B","C","D"],"k":2,"ex":"An intrabronchial obstruction prevents ventilation of the distal lung segment. Gas is absorbed from the obstructed region and the alveoli collapse (resorption atelectasis). An inhaled foreign body and a mucus plug can both cause this mechanism.","more":"An intrabronchial obstruction prevents ventilation of the distal lung segment. Gas is absorbed from the obstructed region and the alveoli collapse (resorption atelectasis). An inhaled foreign body and a mucus plug can both cause this mechanism.\n\nCurriculum alignment: Respiratory 2024, pp.3–4, p.29: airway obstruction and foreign-body aspiration; general respiratory pathophysiology.\n\nHigh-yield point: An intrabronchial obstruction prevents ventilation of the distal lung segment.","ao":true,"eb":true,"aoClass":"Accepted","aoReview":false,"aoTitle":"CH08-Q036 — Q36: Causes of atelectasis due to intrabronchial obstruction","aoSource":"Question-bank MD page 110 · Printed page 198 · Answer-key PDF page 116 · Original question Q36","aoSystem":"الجهاز التنفسي","aoPart":"","kx":false,"ebSourceFile":"Paediatrics_Pulmonology_Accepted.md","_genhy":true},{"id":"EB-paediatrics-pulmonology-accepted-CH08-Q039","spec":"eb-respiratory","topic":0,"tag":"Egyptian book","kind":"Pathophysiology","q":"Factorsinthepathogenesisofthebronchialasthma, except","o":["Smoothmusclespasm","Mucosaledema","Hypersecretion","Obstruction"],"ol":["A","B","C","D"],"k":3,"ex":"Asthma involves variable airway narrowing due to bronchial smooth-muscle constriction, mucosal inflammation/edema and increased mucus production. Airflow obstruction is the functional consequence of these processes rather than an initiating mechanism, so option d is the intended exception.","more":"Asthma involves variable airway narrowing due to bronchial smooth-muscle constriction, mucosal inflammation/edema and increased mucus production. Airflow obstruction is the functional consequence of these processes rather than an initiating mechanism, so option d is the intended exception.\n\nCurriculum alignment: Respiratory 2024, pp.32–36: asthma pathogenesis, airway inflammation and bronchoconstriction.\n\nHigh-yield point: Asthma involves variable airway narrowing due to bronchial smooth-muscle constriction, mucosal inflammation/edema and increased mucus production.","ao":true,"eb":true,"aoClass":"Accepted","aoReview":false,"aoTitle":"CH08-Q039 — Q39: Factors in the pathogenesis of bronchial asthma: exception","aoSource":"Question-bank MD page 110 · Printed page 198 · Answer-key PDF page 116 · Original question Q39","aoSystem":"الجهاز التنفسي","aoPart":"","kx":false,"ebSourceFile":"Paediatrics_Pulmonology_Accepted.md","_genhy":true},{"id":"EB-paediatrics-pulmonology-accepted-CH08-Q040","spec":"eb-respiratory","topic":0,"tag":"Egyptian book","kind":"Pathophysiology","q":"Chemicalmediatorsoftheasthma,except","o":["Bradykinin","SRSA","Eosinophilicchemotacticfactor","Serotinin"],"ol":["A","B","C","D"],"k":3,"ex":"Asthma inflammation involves multiple mediators including leukotrienes (historically SRS-A), bradykinin and eosinophil chemotactic factors. Serotonin is not usually presented as a principal mediator in the classic asthma mediator lists, so it is the intended exception.","more":"Asthma inflammation involves multiple mediators including leukotrienes (historically SRS-A), bradykinin and eosinophil chemotactic factors. Serotonin is not usually presented as a principal mediator in the classic asthma mediator lists, so it is the intended exception.\n\nCurriculum alignment: Respiratory 2024, pp.32–34: asthma pathophysiology and inflammatory mediators.\n\nHigh-yield point: Asthma inflammation involves multiple mediators including leukotrienes (historically SRS-A), bradykinin and eosinophil chemotactic factors.","ao":true,"eb":true,"aoClass":"Accepted","aoReview":false,"aoTitle":"CH08-Q040 — Q40: Asthma chemical mediator: exception","aoSource":"Question-bank MD page 110 · Printed page 198 · Answer-key PDF page 116 · Original question Q40","aoSystem":"الجهاز التنفسي","aoPart":"","kx":false,"ebSourceFile":"Paediatrics_Pulmonology_Accepted.md","_genhy":true},{"id":"EB-paediatrics-pulmonology-accepted-CH08-Q043","spec":"eb-respiratory","topic":0,"tag":"Egyptian book","kind":"Pathophysiology","q":"Theearliestacidbasedisturbanceinasthma","o":["Respiratoryacidosis","Respiratoryalkalosis","Metabolicacidosis","Metabolicalkalosis"],"ol":["A","B","C","D"],"k":1,"ex":"Early in an acute asthma exacerbation, increased respiratory drive and hyperventilation commonly reduce PaCO2, producing respiratory alkalosis. A normal or rising PaCO2 in a patient with severe distress may signal fatigue and impending ventilatory failure.","more":"Early in an acute asthma exacerbation, increased respiratory drive and hyperventilation commonly reduce PaCO2, producing respiratory alkalosis. A normal or rising PaCO2 in a patient with severe distress may signal fatigue and impending ventilatory failure.\n\nCurriculum alignment: Respiratory 2024, asthma acute exacerbation and blood-gas/respiratory physiology.\n\nHigh-yield point: Early in an acute asthma exacerbation, increased respiratory drive and hyperventilation commonly reduce PaCO2, producing respiratory alkalosis.","ao":true,"eb":true,"aoClass":"Accepted","aoReview":false,"aoTitle":"CH08-Q043 — Q43: Earliest acid–base disturbance during an asthma attack","aoSource":"Question-bank MD page 110 · Printed page 198 · Answer-key PDF page 116 · Original question Q43","aoSystem":"الجهاز التنفسي","aoPart":"","kx":false,"ebSourceFile":"Paediatrics_Pulmonology_Accepted.md","_genhy":true},{"id":"EB-paediatrics-pulmonology-accepted-CH08-Q044","spec":"eb-respiratory","topic":0,"tag":"Egyptian book","kind":"Investigation","q":"Eosinophilcountisreducedinasthmain","o":["Infection","Steroidadministration","Both","None"],"ol":["A","B","C","D"],"k":2,"ex":"Systemic corticosteroids cause eosinopenia through redistribution and suppression of eosinophil survival. Acute bacterial infection/stress may also reduce circulating eosinophils. Thus both listed situations can reduce the peripheral eosinophil count, although this finding is not a diagnostic marker by itself.","more":"Systemic corticosteroids cause eosinopenia through redistribution and suppression of eosinophil survival. Acute bacterial infection/stress may also reduce circulating eosinophils. Thus both listed situations can reduce the peripheral eosinophil count, although this finding is not a diagnostic marker by itself.\n\nCurriculum alignment: Respiratory 2024, asthma investigations and treatment; general hematologic response to infection/steroids.\n\nHigh-yield point: Systemic corticosteroids cause eosinopenia through redistribution and suppression of eosinophil survival.","ao":true,"eb":true,"aoClass":"Accepted","aoReview":false,"aoTitle":"CH08-Q044 — Q44: Situations in which eosinophil count is reduced in asthma","aoSource":"Question-bank MD page 111 · Printed page 199 · Answer-key PDF page 116 · Original question Q44","aoSystem":"الجهاز التنفسي","aoPart":"","kx":false,"ebSourceFile":"Paediatrics_Pulmonology_Accepted.md","_genhy":true},{"id":"EB-paediatrics-pulmonology-accepted-CH08-Q048","spec":"eb-respiratory","topic":0,"tag":"Egyptian book","kind":"Pharmacology","q":"Commonly used bronchodilators in bronchial asthmaexcept","o":["βadrenergic","Xanthihederivative","Mastcellstabilizer","Atropinederivative"],"ol":["A","B","C","D"],"k":2,"ex":"Beta-2 agonists and methylxanthines/theophylline have bronchodilator activity; antimuscarinic agents such as ipratropium also produce bronchodilation. Mast-cell stabilizers (for example cromolyn) are preventive anti-inflammatory agents and do not act as bronchodilators.","more":"Beta-2 agonists and methylxanthines/theophylline have bronchodilator activity; antimuscarinic agents such as ipratropium also produce bronchodilation. Mast-cell stabilizers (for example cromolyn) are preventive anti-inflammatory agents and do not act as bronchodilators.\n\nCurriculum alignment: Respiratory 2024, pp.32–36: asthma pharmacology and bronchodilator classes.\n\nHigh-yield point: Beta-2 agonists and methylxanthines/theophylline have bronchodilator activity; antimuscarinic agents such as ipratropium also produce bronchodilation.","ao":true,"eb":true,"aoClass":"Accepted","aoReview":false,"aoTitle":"CH08-Q048 — Q48: Commonly used bronchodilator classes in asthma: exception","aoSource":"Question-bank MD page 111 · Printed page 199 · Answer-key PDF page 116 · Original question Q48","aoSystem":"الجهاز التنفسي","aoPart":"","kx":false,"ebSourceFile":"Paediatrics_Pulmonology_Accepted.md","_genhy":true},{"id":"EB-paediatrics-pulmonology-accepted-CH08-Q049","spec":"eb-respiratory","topic":0,"tag":"Egyptian book","kind":"Pharmacology","q":"Modeofactionofdisodiumchromoglycate","o":["Bronchodilators","Mastcellstabilizer","Both","None"],"ol":["A","B","C","D"],"k":1,"ex":"Disodium cromoglycate (cromolyn) stabilizes mast cells and reduces mediator release. It is a prophylactic controller, not a rescue bronchodilator, and does not reverse acute bronchospasm.","more":"Disodium cromoglycate (cromolyn) stabilizes mast cells and reduces mediator release. It is a prophylactic controller, not a rescue bronchodilator, and does not reverse acute bronchospasm.\n\nCurriculum alignment: Respiratory 2024, asthma pharmacology.\n\nHigh-yield point: Disodium cromoglycate (cromolyn) stabilizes mast cells and reduces mediator release.","ao":true,"eb":true,"aoClass":"Accepted","aoReview":false,"aoTitle":"CH08-Q049 — Q49: Mechanism of disodium cromoglycate","aoSource":"Question-bank MD page 111 · Printed page 199 · Answer-key PDF page 116 · Original question Q49","aoSystem":"الجهاز التنفسي","aoPart":"","kx":false,"ebSourceFile":"Paediatrics_Pulmonology_Accepted.md","_genhy":true},{"id":"EB-paediatrics-pulmonology-accepted-CH08-Q051","spec":"eb-respiratory","topic":0,"tag":"Egyptian book","kind":"Pathophysiology","q":"Factorsinthepathogenesisofbronchiectasis","o":["Infection","Obstruction","Both","None"],"ol":["A","B","C","D"],"k":2,"ex":"Bronchiectasis is characterized by permanent abnormal dilation of bronchi due to damage to the bronchial wall. Infection and impaired drainage/airway obstruction reinforce one another in a cycle of infection, inflammation, structural damage and further secretion retention.","more":"Bronchiectasis is characterized by permanent abnormal dilation of bronchi due to damage to the bronchial wall. Infection and impaired drainage/airway obstruction reinforce one another in a cycle of infection, inflammation, structural damage and further secretion retention.\n\nCurriculum alignment: Respiratory 2024, pp.27–28 and pp.31–32: bronchiectasis, causes and pathophysiology.\n\nHigh-yield point: Bronchiectasis is characterized by permanent abnormal dilation of bronchi due to damage to the bronchial wall.","ao":true,"eb":true,"aoClass":"Accepted","aoReview":false,"aoTitle":"CH08-Q051 — Q51: Factors in the pathogenesis of bronchiectasis","aoSource":"Question-bank MD page 111 · Printed page 199 · Answer-key PDF page 116 · Original question Q51","aoSystem":"الجهاز التنفسي","aoPart":"","kx":false,"ebSourceFile":"Paediatrics_Pulmonology_Accepted.md","_genhy":true},{"id":"EB-paediatrics-pulmonology-accepted-CH08-Q053","spec":"eb-respiratory","topic":0,"tag":"Egyptian book","kind":"Differential Diagnosis","q":"Commoncausesofbronchiectasis,except","o":["Postmeasles","Bronchiolitis","Tuberculosis","Whoopingcough"],"ol":["A","B","C","D"],"k":1,"ex":"Bronchiectasis can follow severe/recurrent infections such as measles, tuberculosis and pertussis, as well as cystic fibrosis and primary ciliary dyskinesia. Bronchiolitis is not a classic direct cause in the same way; severe adenoviral bronchiolitis may lead to obliterative bronchiolitis rather than typical bronchiectasis.","more":"Bronchiectasis can follow severe/recurrent infections such as measles, tuberculosis and pertussis, as well as cystic fibrosis and primary ciliary dyskinesia. Bronchiolitis is not a classic direct cause in the same way; severe adenoviral bronchiolitis may lead to obliterative bronchiolitis rather than typical bronchiectasis.\n\nCurriculum alignment: Respiratory 2024, pp.27–28 and pp.31–32: bronchiectasis causes including post-infectious disease, TB and pertussis.\n\nHigh-yield point: Bronchiectasis can follow severe/recurrent infections such as measles, tuberculosis and pertussis, as well as cystic fibrosis and primary ciliary dyskinesia.","ao":true,"eb":true,"aoClass":"Accepted","aoReview":false,"aoTitle":"CH08-Q053 — Q53: Cause of bronchiectasis: exception","aoSource":"Question-bank MD page 111 · Printed page 199 · Answer-key PDF page 116 · Original question Q53","aoSystem":"الجهاز التنفسي","aoPart":"","kx":false,"ebSourceFile":"Paediatrics_Pulmonology_Accepted.md","_genhy":true},{"id":"EB-paediatrics-pulmonology-accepted-CH08-Q056","spec":"eb-respiratory","topic":0,"tag":"Egyptian book","kind":"Diagnosis","q":"Thecommonestcauseofbronchiolitis","o":["Respiratorysynctialvirus","Pneumococcus","Enterovirus","Haemophilus"],"ol":["A","B","C","D"],"k":0,"ex":"Respiratory syncytial virus (RSV) is the most common cause of acute bronchiolitis in infants. Other viruses, including rhinovirus, human metapneumovirus and parainfluenza, can also cause bronchiolitis.","more":"Respiratory syncytial virus (RSV) is the most common cause of acute bronchiolitis in infants. Other viruses, including rhinovirus, human metapneumovirus and parainfluenza, can also cause bronchiolitis.\n\nCurriculum alignment: Respiratory 2024, pp.18–21: bronchiolitis and RSV.\n\nHigh-yield point: Respiratory syncytial virus (RSV) is the most common cause of acute bronchiolitis in infants.","ao":true,"eb":true,"aoClass":"Accepted","aoReview":false,"aoTitle":"CH08-Q056 — Q56: Commonest cause of bronchiolitis","aoSource":"Question-bank MD page 112 · Printed page 200 · Answer-key PDF page 116 · Original question Q56","aoSystem":"الجهاز التنفسي","aoPart":"","kx":false,"ebSourceFile":"Paediatrics_Pulmonology_Accepted.md","_genhy":true},{"id":"EB-paediatrics-pulmonology-accepted-CH08-Q057","spec":"eb-respiratory","topic":0,"tag":"Egyptian book","kind":"Diagnosis","q":"Hyalinemembraneinthelungisseenin","o":["Respiratorydistresssyndrome","Pneumococcalpneumonia","Pulmonaryedema","Viralhepatitis"],"ol":["A","B","C","D"],"k":0,"ex":"Hyaline membranes line alveoli in neonatal respiratory distress syndrome (RDS) caused by surfactant deficiency, classically in premature infants. They consist of fibrin-rich material and cellular debris associated with alveolar epithelial injury.","more":"Hyaline membranes line alveoli in neonatal respiratory distress syndrome (RDS) caused by surfactant deficiency, classically in premature infants. They consist of fibrin-rich material and cellular debris associated with alveolar epithelial injury.\n\nCurriculum alignment: Neonatology 2024–25, RDS/surfactant deficiency; Respiratory 2024, neonatal respiratory distress.\n\nHigh-yield point: Hyaline membranes line alveoli in neonatal respiratory distress syndrome (RDS) caused by surfactant deficiency, classically in premature infants.","ao":true,"eb":true,"aoClass":"Accepted","aoReview":false,"aoTitle":"CH08-Q057 — Q57: Condition associated with hyaline membranes in the lung","aoSource":"Question-bank MD page 112 · Printed page 200 · Answer-key PDF page 116 · Original question Q57","aoSystem":"الجهاز التنفسي","aoPart":"","kx":false,"ebSourceFile":"Paediatrics_Pulmonology_Accepted.md","_genhy":true},{"id":"EB-paediatrics-pulmonology-accepted-CH08-Q058","spec":"eb-respiratory","topic":0,"tag":"Egyptian book","kind":"Treatment","q":"Thetreatmentofthebronchiolitis","o":["Humidifiedoxygen","Steroids","Antibiotics","Viralhepatitis"],"ol":["A","B","C","D"],"k":0,"ex":"Management of bronchiolitis is mainly supportive: maintain hydration and feeding, clear nasal secretions when needed, and provide supplemental oxygen when hypoxemic. Routine corticosteroids and antibiotics are not recommended for uncomplicated viral bronchiolitis; antibiotics are reserved for suspected bacterial coinfection. “Humidified oxygen” is an older formulation, but oxygen support for hypoxemia is appropriate.","more":"Management of bronchiolitis is mainly supportive: maintain hydration and feeding, clear nasal secretions when needed, and provide supplemental oxygen when hypoxemic. Routine corticosteroids and antibiotics are not recommended for uncomplicated viral bronchiolitis; antibiotics are reserved for suspected bacterial coinfection. “Humidified oxygen” is an older formulation, but oxygen support for hypoxemia is appropriate.\n\nCurriculum alignment: Respiratory 2024, pp.18–21: bronchiolitis management is supportive; Neonatology respiratory support where relevant.\n\nHigh-yield point: Management of bronchiolitis is mainly supportive: maintain hydration and feeding, clear nasal secretions when needed, and provide supplemental oxygen when hypoxemic.","ao":true,"eb":true,"aoClass":"Accepted","aoReview":false,"aoTitle":"CH08-Q058 — Q58: Treatment of bronchiolitis","aoSource":"Question-bank MD page 112 · Printed page 200 · Answer-key PDF page 116 · Original question Q58","aoSystem":"الجهاز التنفسي","aoPart":"","kx":false,"ebSourceFile":"Paediatrics_Pulmonology_Accepted.md","_genhy":true},{"id":"EB-paediatrics-pulmonology-accepted-CH08-Q062","spec":"eb-respiratory","topic":0,"tag":"Egyptian book","kind":"Complications","q":"In staphylococcalpneumonia,acute respiratory distressisdueto","o":["Pneumotoceleformation","Pleuraleffusion","Tensionpneumothorax","Spreadingpneumonia"],"ol":["A","B","C","D"],"k":0,"ex":"Staphylococcal pneumonia may produce pneumatoceles (thin-walled air-filled cavities). Rapid expansion or rupture can cause respiratory compromise, pneumothorax or tension pneumothorax. Pneumatocele formation is a classic mechanism in this question-bank item.","more":"Staphylococcal pneumonia may produce pneumatoceles (thin-walled air-filled cavities). Rapid expansion or rupture can cause respiratory compromise, pneumothorax or tension pneumothorax. Pneumatocele formation is a classic mechanism in this question-bank item.\n\nCurriculum alignment: Respiratory 2024, pp.22–24: staphylococcal pneumonia and complications.\n\nHigh-yield point: Staphylococcal pneumonia may produce pneumatoceles (thin-walled air-filled cavities).","ao":true,"eb":true,"aoClass":"Accepted","aoReview":false,"aoTitle":"CH08-Q062 — Q62: Cause of acute respiratory distress in staphylococcal pneumonia","aoSource":"Question-bank MD page 112 · Printed page 200 · Answer-key PDF page 116 · Original question Q62","aoSystem":"الجهاز التنفسي","aoPart":"","kx":false,"ebSourceFile":"Paediatrics_Pulmonology_Accepted.md","_genhy":true},{"id":"EB-paediatrics-pulmonology-accepted-CH08-Q067","spec":"eb-respiratory","topic":0,"tag":"Egyptian book","kind":"Differential Diagnosis","q":"Thefollowingdoesnotcausepneumonia","o":["Measles","Mumps","Varicella","Cytomegalovirus"],"ol":["A","B","C","D"],"k":1,"ex":"Measles, varicella and CMV can cause pneumonia. Mumps is not a common cause of pediatric pneumonia, although rare respiratory involvement has been reported. The answer is acceptable as a “not common” association, but the wording says “does not cause,” which is too absolute.","more":"Measles, varicella and CMV can cause pneumonia. Mumps is not a common cause of pediatric pneumonia, although rare respiratory involvement has been reported. The answer is acceptable as a “not common” association, but the wording says “does not cause,” which is too absolute.\n\nCurriculum alignment: Respiratory 2024, pneumonia; Infectious 2024, viral disease sections. Extended Beyond Core Curriculum because rare mumps pulmonary involvement is a nuance beyond basic teaching.\n\nHigh-yield point: Measles, varicella and CMV can cause pneumonia.","ao":true,"eb":true,"aoClass":"Accepted","aoReview":false,"aoTitle":"CH08-Q067 — Q67: Virus not commonly associated with pneumonia","aoSource":"Question-bank MD page 113 · Printed page 201 · Answer-key PDF page 116 · Original question Q67","aoSystem":"الجهاز التنفسي","aoPart":"","kx":false,"ebSourceFile":"Paediatrics_Pulmonology_Accepted.md","_genhy":true},{"id":"EB-paediatrics-pulmonology-accepted-CH08-Q068","spec":"eb-respiratory","topic":0,"tag":"Egyptian book","kind":"Diagnosis","q":"Thecommonestcauseofthestridorinnewbornis","o":["Laryngomalacea","Meconiumaspiration","Foreignbody","Birthinjury"],"ol":["A","B","C","D"],"k":0,"ex":"Laryngomalacia is the most common cause of congenital/chronic stridor in infants. It is caused by dynamic collapse of supraglottic structures during inspiration and typically produces inspiratory stridor that worsens with feeding, crying or supine position.","more":"Laryngomalacia is the most common cause of congenital/chronic stridor in infants. It is caused by dynamic collapse of supraglottic structures during inspiration and typically produces inspiratory stridor that worsens with feeding, crying or supine position.\n\nCurriculum alignment: Respiratory 2024, pp.11–12: chronic stridor/laryngomalacia.\n\nHigh-yield point: Laryngomalacia is the most common cause of congenital/chronic stridor in infants.","ao":true,"eb":true,"aoClass":"Accepted","aoReview":false,"aoTitle":"CH08-Q068 — Q68: Commonest cause of stridor in a newborn","aoSource":"Question-bank MD page 113 · Printed page 201 · Answer-key PDF page 116 · Original question Q68","aoSystem":"الجهاز التنفسي","aoPart":"","kx":false,"ebSourceFile":"Paediatrics_Pulmonology_Accepted.md","_genhy":true},{"id":"EB-paediatrics-pulmonology-accepted-CH08-Q069","spec":"eb-respiratory","topic":0,"tag":"Egyptian book","kind":"Treatment","q":"Inachildwithexercise-inducedasthma,whichis done","o":["Prophylaxiswithsteroids","Prophylaxiswiththeophyllin","Prophylaxiswithβ-2agonist","Breathingexercise"],"ol":["A","B","C","D"],"k":2,"ex":"A short-acting beta-2 agonist taken before exercise has traditionally been used to prevent exercise-induced bronchoconstriction. Current asthma strategies increasingly emphasize inhaled corticosteroid-containing treatment rather than SABA-only management for many patients; regimen choice depends on age, asthma control and local guideline. The question is clinically relevant but reflects a simplified traditional approach.","more":"A short-acting beta-2 agonist taken before exercise has traditionally been used to prevent exercise-induced bronchoconstriction. Current asthma strategies increasingly emphasize inhaled corticosteroid-containing treatment rather than SABA-only management for many patients; regimen choice depends on age, asthma control and local guideline. The question is clinically relevant but reflects a simplified traditional approach.\n\nCurriculum alignment: Respiratory 2024, pp.32–36: asthma triggers and treatment; Extended Beyond Core Curriculum because treatment strategy is evolving and SABA-only use is no longer preferred in many guideline pathways.\n\nHigh-yield point: A short-acting beta-2 agonist taken before exercise has traditionally been used to prevent exercise-induced bronchoconstriction.","ao":true,"eb":true,"aoClass":"Accepted","aoReview":false,"aoTitle":"CH08-Q069 — Q69: Prophylaxis for exercise-induced asthma","aoSource":"Question-bank MD page 113 · Printed page 201 · Answer-key PDF page 116 · Original question Q69","aoSystem":"الجهاز التنفسي","aoPart":"","kx":false,"ebSourceFile":"Paediatrics_Pulmonology_Accepted.md","_genhy":true},{"id":"EB-paediatrics-pulmonology-accepted-CH08-Q070","spec":"eb-respiratory","topic":0,"tag":"Egyptian book","kind":"Diagnosis","q":"Croupsyndromeisusuallycausedby","o":["Rhinovirusas","CoxsackieBvirus","CoxsackieAvirus","Parainfiuenzavirus"],"ol":["A","B","C","D"],"k":3,"ex":"Croup (laryngotracheobronchitis) is most commonly caused by parainfluenza viruses, especially types 1 and 2. It produces a barking cough, hoarseness and inspiratory stridor.","more":"Croup (laryngotracheobronchitis) is most commonly caused by parainfluenza viruses, especially types 1 and 2. It produces a barking cough, hoarseness and inspiratory stridor.\n\nCurriculum alignment: Respiratory 2024, pp.14–17: croup etiology and clinical picture.\n\nHigh-yield point: Croup (laryngotracheobronchitis) is most commonly caused by parainfluenza viruses, especially types 1 and 2.","ao":true,"eb":true,"aoClass":"Accepted","aoReview":false,"aoTitle":"CH08-Q070 — Q70: Usual viral cause of croup","aoSource":"Question-bank MD page 113 · Printed page 201 · Answer-key PDF page 116 · Original question Q70","aoSystem":"الجهاز التنفسي","aoPart":"","kx":false,"ebSourceFile":"Paediatrics_Pulmonology_Accepted.md","_genhy":true},{"id":"EB-paediatrics-pulmonology-accepted-CH08-Q075","spec":"eb-respiratory","topic":0,"tag":"Egyptian book","kind":"Diagnosis","q":"The clinicalsign ofhyaline membrane disease generallyappears","o":["Inthefirst6hroflife","Between36-48hroflife","Between12-24hroflife","After48hroflife"],"ol":["A","B","C","D"],"k":0,"ex":"Neonatal respiratory distress syndrome due to surfactant deficiency usually begins soon after birth, often within the first several hours, and may worsen over the first 24–48 hours before improving as surfactant production increases. The first six hours is the expected option.","more":"Neonatal respiratory distress syndrome due to surfactant deficiency usually begins soon after birth, often within the first several hours, and may worsen over the first 24–48 hours before improving as surfactant production increases. The first six hours is the expected option.\n\nCurriculum alignment: Neonatology 2024–25, RDS; Respiratory 2024, neonatal respiratory distress.\n\nHigh-yield point: Neonatal respiratory distress syndrome due to surfactant deficiency usually begins soon after birth, often within the first several hours, and may worsen over the first 24–48 hours before improving as surfactant production increases.","ao":true,"eb":true,"aoClass":"Accepted","aoReview":false,"aoTitle":"CH08-Q075 — Q75: Onset of clinical signs of neonatal hyaline membrane disease","aoSource":"Question-bank MD page 114 · Printed page 202 · Answer-key PDF page 116 · Original question Q75","aoSystem":"الجهاز التنفسي","aoPart":"","kx":false,"ebSourceFile":"Paediatrics_Pulmonology_Accepted.md","_genhy":true},{"id":"EB-paediatrics-pulmonology-accepted-CH08-Q076","spec":"eb-respiratory","topic":0,"tag":"Egyptian book","kind":"Investigation","q":"BatwingappearanceinX-rayisseenin","o":["Bronchialasthma","Mitralstenosis","Cardiogenicpulmonaryedema","Pulmonaryembolism"],"ol":["A","B","C","D"],"k":2,"ex":"A bilateral perihilar “bat-wing” or “butterfly” pattern is classic for pulmonary edema, particularly cardiogenic pulmonary edema. It reflects central alveolar/interstitial fluid accumulation.","more":"A bilateral perihilar “bat-wing” or “butterfly” pattern is classic for pulmonary edema, particularly cardiogenic pulmonary edema. It reflects central alveolar/interstitial fluid accumulation.\n\nCurriculum alignment: Respiratory 2024, pp.22–24 and Cardiology 2024, heart failure/pulmonary congestion.\n\nHigh-yield point: A bilateral perihilar “bat-wing” or “butterfly” pattern is classic for pulmonary edema, particularly cardiogenic pulmonary edema.","ao":true,"eb":true,"aoClass":"Accepted","aoReview":false,"aoTitle":"CH08-Q076 — Q76: Bat-wing appearance on chest X-ray","aoSource":"Question-bank MD page 114 · Printed page 202 · Answer-key PDF page 116 · Original question Q76","aoSystem":"الجهاز التنفسي","aoPart":"","kx":false,"ebSourceFile":"Paediatrics_Pulmonology_Accepted.md","_genhy":true},{"id":"EB-paediatrics-pulmonology-accepted-CH08-Q079","spec":"eb-respiratory","topic":0,"tag":"Egyptian book","kind":"Diagnosis","q":"Thesignofpneumoniainoneyearoldchild","o":["Intercostalretraction","Temperature>39.5andRR60","Gruntingandrespiratoryrate60","Alloftheabove"],"ol":["A","B","C","D"],"k":2,"ex":"Pneumonia in young children may present with tachypnea, chest indrawing/retractions, grunting, fever, hypoxemia, poor feeding and general danger signs. The respiratory-rate threshold varies by age and guideline; a rate of 60/min is clearly high for a one-year-old. All listed clinical patterns are compatible with pneumonia or significant respiratory distress.","more":"Pneumonia in young children may present with tachypnea, chest indrawing/retractions, grunting, fever, hypoxemia, poor feeding and general danger signs. The respiratory-rate threshold varies by age and guideline; a rate of 60/min is clearly high for a one-year-old. All listed clinical patterns are compatible with pneumonia or significant respiratory distress.\n\nCurriculum alignment: Respiratory 2024, pp.6–8 and pp.22–24: pneumonia clinical assessment and signs of respiratory distress.\n\nHigh-yield point: Pneumonia in young children may present with tachypnea, chest indrawing/retractions, grunting, fever, hypoxemia, poor feeding and general danger signs.","ao":true,"eb":true,"aoClass":"Accepted","aoReview":false,"aoTitle":"CH08-Q079 — Q79: Clinical signs of pneumonia in a one-year-old child","aoSource":"Question-bank MD page 114 · Printed page 202 · Answer-key PDF page 116 · Original question Q79","aoSystem":"الجهاز التنفسي","aoPart":"","kx":false,"ebSourceFile":"Paediatrics_Pulmonology_Accepted.md","_genhy":true},{"id":"EB-paediatrics-miscellaneous-topics-accepted-Q91","spec":"eb-respiratory","topic":0,"tag":"Egyptian book","kind":"Respiratory examination / breath sounds","q":"Thetypesofthebronchialbreathing","o":["Tubular","Cavernous","Both","None"],"ol":["A","B","C","D"],"k":2,"ex":"Bronchial breathing may be described as tubular (heard over consolidation with a patent bronchus) or cavernous (heard over a superficial cavity communicating with a bronchus). Both are recognized descriptive types.","more":"Bronchial breathing may be described as tubular (heard over consolidation with a patent bronchus) or cavernous (heard over a superficial cavity communicating with a bronchus). Both are recognized descriptive types. **Why the others are wrong:** (a) Tubular: a type of bronchial breathing. (b) Cavernous: a type of bronchial breathing. (c) Both: correct. (d) None: incorrect.\n\nCurriculum alignment: Respiratory 2024: added sounds and types of bronchial breathing. **High-yield point / Review Notes:** Bronchial breathing over a peripheral lung field is abnormal and suggests altered transmission through lung tissue.\n\nHigh-yield point: Bronchial breathing may be described as tubular (heard over consolidation with a patent bronchus) or cavernous (heard over a superficial cavity communicating with a bronchus).","ao":true,"eb":true,"aoClass":"Accepted","aoReview":false,"aoTitle":"Q91 — Respiratory examination / breath sounds","aoSource":"Question-bank MD p.161 · printed p.311 · answer-key PDF p.169 · original Q91","aoSystem":"الجهاز التنفسي","aoPart":"","kx":false,"ebSourceFile":"Paediatrics_Miscellaneous_Topics_Accepted.md","_genhy":true},{"id":"EB-paediatrics-miscellaneous-topics-accepted-Q94","spec":"eb-respiratory","topic":0,"tag":"Egyptian book","kind":"Respiratory examination / percussion","q":"Resonantpercussionnoteisfoundin","o":["Emphysema","Pneumothorax","Both","None"],"ol":["A","B","C","D"],"k":3,"ex":"Emphysema and pneumothorax classically produce a hyperresonant percussion note, not simply the normal resonant note. The distinction in terminology matters: “resonant” is the normal note over healthy aerated lung; “hyperresonant” is an abnormally more resonant note. Read literally, none of the options gives a hyperresonant response.","more":"Emphysema and pneumothorax classically produce a hyperresonant percussion note, not simply the normal resonant note. The distinction in terminology matters: “resonant” is the normal note over healthy aerated lung; “hyperresonant” is an abnormally more resonant note. Read literally, none of the options gives a hyperresonant response. **Why the others are wrong:** (a) Emphysema: produces hyperresonance. (b) Pneumothorax: typically hyperresonant/tympanitic. (c) Both: would be correct if the stem said “hyperresonant”. (d) None: best answer to the literal wording “resonant percussion note” if it means the abnormal finding sought; source key d therefore likely reflects a terminology distinction.\n\nCurriculum alignment: Respiratory 2024: percussion notes and hyperresonance. **High-yield point / Review Notes:** The question is usable with an explicit teaching clarification; do not conflate normal resonance with hyperresonance.\n\nHigh-yield point: Emphysema and pneumothorax classically produce a hyperresonant percussion note, not simply the normal resonant note.","ao":true,"eb":true,"aoClass":"Accepted","aoReview":false,"aoTitle":"Q94 — Respiratory examination / percussion","aoSource":"Question-bank MD p.161 · printed p.311 · answer-key PDF p.169 · original Q94","aoSystem":"الجهاز التنفسي","aoPart":"","kx":false,"ebSourceFile":"Paediatrics_Miscellaneous_Topics_Accepted.md","_genhy":true},{"id":"EB-paediatrics-miscellaneous-topics-accepted-Q95","spec":"eb-respiratory","topic":0,"tag":"Egyptian book","kind":"Respiratory examination / percussion","q":"Impairedpercussionnoteispresent","o":["Consolidation","Pleuraleffusion","Both","None"],"ol":["A","B","C","D"],"k":2,"ex":"Both pulmonary consolidation and pleural effusion produce a dull or impaired percussion note because they replace or separate normally air-filled lung from the chest wall.","more":"Both pulmonary consolidation and pleural effusion produce a dull or impaired percussion note because they replace or separate normally air-filled lung from the chest wall. **Why the others are wrong:** (a) Consolidation: produces dullness. (b) Pleural effusion: produces stony dullness. (c) Both: correct. (d) None: incorrect.\n\nCurriculum alignment: Respiratory 2024: percussion in consolidation and pleural effusion. **High-yield point / Review Notes:** Auscultation and tactile vocal fremitus help distinguish consolidation from effusion.\n\nHigh-yield point: Both pulmonary consolidation and pleural effusion produce a dull or impaired percussion note because they replace or separate normally air-filled lung from the chest wall.","ao":true,"eb":true,"aoClass":"Accepted","aoReview":false,"aoTitle":"Q95 — Respiratory examination / percussion","aoSource":"Question-bank MD p.161 · printed p.311 · answer-key PDF p.169 · original Q95","aoSystem":"الجهاز التنفسي","aoPart":"","kx":false,"ebSourceFile":"Paediatrics_Miscellaneous_Topics_Accepted.md","_genhy":true}]);
